import{r as e}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as i,o as r,c as l,b6 as n,J as o,k as d}from"./chunks/framework.BUXTSoD9.js";const A=JSON.parse('{"title":"アイデアからAIプロダクトへ - Easy-Vibe 学習ロードマップ","description":"AIプログラミングをゼロから学び、フルスタック開発まで到達するための学習ロードマップ。Vibe Coding、Claude Code、CursorなどのAI IDEを使いこなし、プロダクト思考、フルスタック開発、AI機能の組み込みまで学びます。","frontmatter":{"title":"アイデアからAIプロダクトへ - Easy-Vibe 学習ロードマップ","description":"AIプログラミングをゼロから学び、フルスタック開発まで到達するための学習ロードマップ。Vibe Coding、Claude Code、CursorなどのAI IDEを使いこなし、プロダクト思考、フルスタック開発、AI機能の組み込みまで学びます。"},"headers":[],"relativePath":"ja-jp/stage-1/learning-map/index.md","filePath":"ja-jp/stage-1/learning-map/index.md"}'),p={name:"ja-jp/stage-1/learning-map/index.md"},I=Object.assign(p,{setup(c){const t=e["ja-jp/stage-1/learning-map"]??[];return(h,a)=>{const s=i("RelatedArticlesSection");return r(),l("div",null,[a[0]||(a[0]=n('<h1 id="アイデアからaiプロダクトへ" tabindex="-1">アイデアからAIプロダクトへ <a class="header-anchor" href="#アイデアからaiプロダクトへ" aria-label="Permalink to “アイデアからAIプロダクトへ”">​</a></h1><div class="info custom-block"><p class="custom-block-title">特別協力</p><p>本コースのテスト、フィードバック、改善にご協力くださった <strong>清華大学深圳国際大学院</strong> の学生の皆さんに、心より感謝いたします。皆さんの意見と貢献のおかげで、このコースはより実践的で学びやすいものになりました。<a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 コントリビューター一覧を見る</a></p></div><p>かつてソフトウェアを作るには、高いハードルがありました。プログラミングを理解し、アルゴリズムを学び、さらに何年ものプロジェクト経験が必要でした。</p><p>しかし今は違います。アイデアさえあれば、AIがコードを書くところから手伝ってくれます。</p><p>これは非常に大きな変化です。<strong>プログラミング言語は、自然言語へと近づいています。</strong></p><p>大規模言語モデル（LLM）の登場により、開発はもはや「一部の技術者だけのもの」ではなく、誰もが使える道具になりつつあります。以前もっとも難しかったのは「どうコードを書くか」でした。今もっとも重要なのは、「<strong>何を作りたいのか</strong>」を明確にすることです。</p><blockquote><p><strong>Vibe Codingとは？</strong> 簡単に言えば、「話すようにプログラミングする」ことです。コードを直接書く代わりに、AIと対話しながら、要件整理、実装、修正、改善を進めていく開発スタイルを指します。</p></blockquote><p>もちろん、AIにコードを書かせることは最初の一歩にすぎません。本当に使えるプロダクトを作るには、次のような課題に向き合う必要があります。</p><ul><li>AIに、読みやすく保守しやすいコードを書かせるにはどうすればよいか？</li><li>断片的なコードを、実際に動くアプリケーションへ組み上げるにはどうすればよいか？</li><li>作ったアプリを公開し、実際のユーザーに使ってもらうにはどうすればよいか？</li><li>テキスト生成、画像認識、音声処理などのAI機能を、自分のプロダクトにどう組み込めばよいか？</li></ul><p>このコースでは、こうした問いへの答えを、実際に手を動かしながら学んでいきます。</p><p>学生、教師、医師、工場や現場で働く人、あるいはこれまで技術にほとんど触れてこなかった人でも大丈夫です。何年もプログラミングを勉強してから始める必要はありません。2週間あれば、動かせて、人に見せられるプロダクトのプロトタイプを作れるようになります。</p><table tabindex="0"><thead><tr><th>あなたの立場</th><th>このコースで得られること</th></tr></thead><tbody><tr><td>学生</td><td>課題、コンテスト、起業アイデアを、自分の手で形にできるようになります</td></tr><tr><td>社会人</td><td>繰り返し作業を自動化し、仕事の効率を高め、場合によっては副業の土台も作れます</td></tr><tr><td>プロダクトマネージャー / デザイナー</td><td>紙やスライド上のアイデアを、上司や顧客に見せられる動くデモへ変えられます</td></tr><tr><td>起業家 / 中小企業の経営者</td><td>高額な外注に頼らず、低コストでアイデアを検証し、MVPを作れます</td></tr><tr><td>教師 / 教育関係者</td><td>教材、授業支援ツール、自動出題ツールなどを作り、教育の効率を高められます</td></tr><tr><td>医師 / 弁護士 / 専門職</td><td>専門業務の一部を自動化し、自分専用の効率化ツールを作れます</td></tr><tr><td>すべての人</td><td>AIを使って、生活や仕事の具体的な困りごとを解決できます</td></tr></tbody></table><p>AI時代においては、技術そのものよりも、アイデアと実行力の価値がますます高まっています。</p><h2 id="成長パス-「aiを使える」から「aiプロダクトを作れる」へ" tabindex="-1">成長パス：「AIを使える」から「AIプロダクトを作れる」へ <a class="header-anchor" href="#成長パス-「aiを使える」から「aiプロダクトを作れる」へ" aria-label="Permalink to “成長パス：「AIを使える」から「AIプロダクトを作れる」へ”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>初心者向け入門</h3><p class="stage-role">AIプログラミングを体験する</p><div class="stage-tags"><span>ヘビゲーム</span><span>ゼロから始める</span><span>Vibe Coding 初体験</span><span>数分で生成</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>第1段階</h3><p class="stage-role">プロダクトマネージャー / 運用担当者</p><div class="stage-tags"><span>AI IDE（Cursor/Claude）</span><span>要件分解 &amp; プロトタイプ</span><span>AI機能の組み込み</span><span>完成デモ開発</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>第2段階</h3><p class="stage-role">初中級エンジニア / 個人開発者</p><div class="stage-tags"><span>Figmaからコードへ</span><span>Supabase データベース</span><span>Stripe 決済連携</span><span>Dify ナレッジベース</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>第3段階</h3><p class="stage-role">上級エンジニア / アーキテクト</p><div class="stage-tags"><span>Web/ミニアプリ/マルチプラットフォーム</span><span>MCP 高度ツール</span><span>RAG &amp; LangGraph</span><span>上級エンジニアの思考法</span></div></div></div><p>この学習パスを進めることで、次の力が身につきます。</p><ul><li><strong>Vibe Codingによる開発力：</strong> Vibe Codingの考え方とAIコーディングツールを使いこなし、開発効率を大きく高めます。構文を丸暗記するのではなく、AIを導いて高品質なコードを生成する方法を学びます。</li><li><strong>フルスタック開発スキル：</strong> UI設計からフロントエンド実装、データベース設計からAPI開発、ローカル開発からクラウドへのデプロイまで、現代的なWebアプリケーション開発の全体像を身につけます。</li><li><strong>AI機能の組み込み力：</strong> さまざまなマルチモーダルAI APIを利用し、テキスト、画像、音声などのAI機能をアプリケーションへ自然に組み込みます。さらにRAGなどの技術を使い、より賢いプロダクトを構築します。</li><li><strong>プロダクト思考と運用力：</strong> ユーザーリサーチ、要件分解、MVP設計、プロダクト改善、決済連携、ユーザー管理まで、プロダクト開発と運用の一連の流れを理解します。</li></ul><h1 id="学び終えると何ができるようになるのか" tabindex="-1">学び終えると何ができるようになるのか？ <a class="header-anchor" href="#学び終えると何ができるようになるのか" aria-label="Permalink to “学び終えると何ができるようになるのか？”">​</a></h1><h2 id="第1段階-最初のプロダクトプロトタイプを作る" tabindex="-1">第1段階：最初のプロダクトプロトタイプを作る <a class="header-anchor" href="#第1段階-最初のプロダクトプロトタイプを作る" aria-label="Permalink to “第1段階：最初のプロダクトプロトタイプを作る”">​</a></h2><p>この段階は、プログラミング経験がまったくない人、あるいは少し触れたことはあるものの自信がない人に向いています。最初から大量の理論を学ぶのではなく、実際に作りながら、AIツールを使ってコードを書く感覚を身につけます。</p><p><strong>学び終えると、次のことができるようになります。</strong></p><ul><li>AIプログラミングツールを使って、Webアプリケーションを自力で作る</li><li>プロダクトのアイデアを、クリックや操作ができるプロトタイプに変える</li><li>プロトタイプにAI機能（例：テキストから画像生成、AIチャットなど）を追加する</li><li>エラーが出たときに、原因を調べて解決する流れを理解する</li></ul><p>簡単に言えば、「実際に動き、人に見せられるもの」を作れるようになります。</p><p>まずは小さなゲームを通じてAIプログラミングを体験します。その後、AIプログラミングツールを使ってコードを書き、エラーを直す方法を学びます。シンプルなページから始め、少しずつ複数ページのアプリケーションへ発展させ、画像生成やAIチャットなどの機能を加えていきます。最後には、ひとつの完成したプロジェクトを自力で作り上げ、自分のアイデアを現実の形にできるようになります。</p><h1 id="なぜプロジェクト形式で学ぶのか" tabindex="-1">なぜプロジェクト形式で学ぶのか？ <a class="header-anchor" href="#なぜプロジェクト形式で学ぶのか" aria-label="Permalink to “なぜプロジェクト形式で学ぶのか？”">​</a></h1><blockquote><p><strong>現実世界の課題</strong></p><p>理由はとてもシンプルです。今の状態のまま現場に入ると、実際のプロジェクトや上司・顧客からの要求に直面したとき、前に進めなくなる可能性があります。現実の仕事では、次のような状況がよく起こります。</p></blockquote><blockquote><p>メンター / 上司：「xxxを作ってください。目標はyyyの効果を出すことです。」</p><p>詳細なドキュメントは？既存のフレームワークは？明確な要件定義書は？──多くの場合、最初から揃っているわけではありません。</p></blockquote><p>実際の仕事の多くは、不確実性の高い環境で、見たことのない問題を解くことです。要件は曖昧で、境界は変わり、誰かが標準解答を教えてくれるわけではありません。自分で調べ、試し、プロトタイプを作り、何度も改善しながら、最終的に「動く・使える・公開できる」解決策を出す必要があります。</p><p>このコースが目指しているのは、比較的安全な学習環境の中で、現実の開発に近い体験を先にしてもらうことです。</p><ul><li>少し難しそうに見えるプロジェクト課題を通じて、問題を分解し、設計し、自分で資料を探す練習をする</li><li>便利すぎるテンプレートに頼り切るのではなく、ある程度規模のあるコードベースを読み、理解し、改造する力を身につける</li><li>アイデアから公開までの流れを通じて、プロダクトを0から1へ立ち上げる一連のプロセスを体験する</li></ul><p>短期的には、この学び方は少し大変に感じるかもしれません。しかし長期的には、就職やキャリア形成における大きな強みになります。問題に向き合う粘り強さ、不確実な状況で突破口を見つける力、AIを単なるデモではなく実際に使えるプロダクトへ落とし込む力が身につきます。</p><h1 id="質問の技術-ai時代の必須スキル" tabindex="-1">質問の技術：AI時代の必須スキル <a class="header-anchor" href="#質問の技術-ai時代の必須スキル" aria-label="Permalink to “質問の技術：AI時代の必須スキル”">​</a></h1><p>AI時代において、質問する力は基本スキルのひとつです。同じコード、同じエラーであっても、<strong>どのように質問するかによって、AIが返す答えの質は大きく変わります</strong>。曖昧な一般論で終わることもあれば、すぐに実行できる具体的な修正案が返ってくることもあります。</p><p><strong>良い習慣をつけましょう。</strong> 「AIに質問すること」を日常の開発フローに組み込み、分からないことや詰まったことがあれば、早めに相談するようにします。</p><h2 id="なぜ必須スキルなのか" tabindex="-1">なぜ必須スキルなのか？ <a class="header-anchor" href="#なぜ必須スキルなのか" aria-label="Permalink to “なぜ必須スキルなのか？”">​</a></h2><ul><li><strong>現実には、完璧なドキュメントはほとんどありません。</strong> 不明確な要件、途中まで作られたコード、断片的なエラー情報に向き合うことが多くあります。</li><li><strong>AIは、いつでも近くにいるメンター兼同僚です。</strong> 質問が上手くなるほど、AIを質の高いペアプログラミング相手として使えるようになります。</li><li><strong>成果の上限は、コミュニケーションで変わります。</strong> 重要な情報を渡し、出力形式や条件を明確にするほど、回答は実用的になります。</li></ul><p><strong>よくある失敗例：</strong> 「なぜエラーが出るの？」とだけ聞いても、AIは推測を並べるしかありません。必要な文脈をそろえて伝えることで、初めて実行可能な解決策が得られます。</p><h2 id="情報をaiに渡す方法-スクリーンショット-vs-コピー-ペースト" tabindex="-1">情報をAIに渡す方法：スクリーンショット vs コピー＆ペースト <a class="header-anchor" href="#情報をaiに渡す方法-スクリーンショット-vs-コピー-ペースト" aria-label="Permalink to “情報をAIに渡す方法：スクリーンショット vs コピー＆ペースト”">​</a></h2><p>どちらの方法も使えますが、向いている場面が異なります。</p><table tabindex="0"><thead><tr><th>方法</th><th>向いている場面</th><th>重要なポイント</th></tr></thead><tbody><tr><td><strong>コピー＆ペースト</strong></td><td>エラースタック、ログ、コード、設定、APIレスポンス</td><td>できるだけ全体を貼る。キーワード1行だけを切り取らない</td></tr><tr><td><strong>スクリーンショット</strong></td><td>UIレイアウトの崩れ、操作の異常、ツール画面でボタンが見つからない場合</td><td>画面全体を写し、重要な場所に印を付ける。できれば一言説明を添える</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ 重要な前提</p><p><strong>すべてのAIが画像入力に対応しているわけではありません。</strong> スクリーンショットを使って相談するには、AI側に画像を理解・分析できるマルチモーダル能力が必要です。現在、画像入力に対応している代表的なAIには、Claude（Anthropic）、GPT-4V / GPT-4o（OpenAI）、Gemini（Google）、通義千問、文心一言などがあります。</p><p><strong>使っているAIが画像入力に対応していない場合</strong>、スクリーンショットは認識されません。その場合は、テキストをコピー＆ペーストして相談してください。</p></div><h2 id="aiに「よく分かる説明」をしてもらうためのプロンプト" tabindex="-1">AIに「よく分かる説明」をしてもらうためのプロンプト <a class="header-anchor" href="#aiに「よく分かる説明」をしてもらうためのプロンプト" aria-label="Permalink to “AIに「よく分かる説明」をしてもらうためのプロンプト”">​</a></h2><p>答えだけでなく、理解そのものを深めたい場合は、次のような指示を使うと説明の質が上がります。</p><blockquote><p><strong>学習型の質問例</strong></p><ul><li>「まず5文でこの概念を説明してください。そのあと、私の理解を確認するための質問をいくつか出してください。」</li><li>「このエラーメッセージを詳しく説明してください。なぜこのエラーが出るのか理解したいです。」</li></ul></blockquote><h1 id="何度やっても解決できず、諦めたくなったら" tabindex="-1">何度やっても解決できず、諦めたくなったら <a class="header-anchor" href="#何度やっても解決できず、諦めたくなったら" aria-label="Permalink to “何度やっても解決できず、諦めたくなったら”">​</a></h1><p>もしかすると、努力の方向が少しずれているだけかもしれません。一人で抱え込まず、作者やティーチングアシスタントに相談してみてください。これまで試したこと、具体的に詰まっている場所、そして今の気持ちを正直に共有しましょう。多くの場合、方向を少し変えたり、必要な知識をひとつ補ったりするだけで、再び前に進めるようになります。</p><h1 id="チュートリアルの設計に気になる点がある場合" tabindex="-1">チュートリアルの設計に気になる点がある場合 <a class="header-anchor" href="#チュートリアルの設計に気になる点がある場合" aria-label="Permalink to “チュートリアルの設計に気になる点がある場合”">​</a></h1><p>いつでも作者に連絡したり、Issueを作成したり、グループや授業内で直接フィードバックしてください。私たちは、このチュートリアルをより分かりやすく、より使いやすいものへ改善していきたいと考えています。どこが分かりにくいか、どこで使いにくさを感じたか、どこで不要な苦労をしたかを、具体的に教えてください。率直で具体的なフィードバックほど、後から学ぶ人の助けになります。</p><h1 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">南京大学 計算機科学技術学科「計算機システム基礎」コース実験</a></li></ul>',51)),o(s,{title:"次に学べること",description:"「AIを使える」から「プロダクトを作れる」への道筋に沿って、さらに先へ進みましょう。",items:d(t)},null,8,["items"])])}}});export{A as __pageData,I as default};
